entries[94535] = { ["name"] = "Gegrillter Dinosaurierschenkel", ["text"] = "Benötigt Stufe 90\nBenutzen: Stellt im Verlauf von 20 Sek. 300000 Gesundheit und ( 75000 / 5 * 20) Mana wieder her. Ihr müsst beim Essen sitzen bleiben. Wenn Ihr mindestens 10 Sekunden mit Essen verbringt, werdet Ihr satt und erhaltet 1 Stunde lang 200 Meisterschaft.\nVerkaufspreis:" }
entries[94536] = { ["name"] = "Unbeschädigter Terrorhornbalg", ["text"] = "Benötigt Stufe 90\nBenutzen: Tarnt Euch als ein Terrorhorn und verringert 10 Min. lang die Distanz, auf die Gegner Euch entdecken können, während Ihr Euch auf der Insel der Riesen befindet.\n\"Sogar die Hörner sind noch dran!\"\nVerkaufspreis:" }
entries[94552] = { ["name"] = "Pläne: Donnerstahlbarren", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Schmiedekunst (500)\nBenutzen: Lehrt Euch die Herstellung von Donnerstahlbarren.\nStellt einen Donnerstahlbarren aus Geistereisenbarren her. Dabei könnt Ihr zusätzliches Wissen über Geistereisen erlangen und einen Schmiedeplan entdecken, den Ihr noch nicht kennt. Dieser Vorgang kann nur einmal am Tag durchgeführt werden.\n\nDonnerstahlbarren\nWird beim Aufheben gebunden\n\"Wird von Schmieden verwendet, um mächtige Objekte herzustellen.\"\nVerkaufspreis:\nBenötigt Geistereisenbarren (10)" }
