entries[95050] = { ["name"] = "DER Messingschlagring", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nFinger\n+566 Stärke\n+849 Ausdauer\nErhöht Eure Waffenkundewertung um + 331.\nErhöht Eure Meisterschaftswertung um + 331.\nBenötigt eine Horde-Rasse\nBenötigt Stufe 90\nBenutzen: Teleportiert den Zaubernden in die Shlae'gararena. (1 Stunde Abklingzeit)\n\"Hiermit ist sichergestellt, dass Ihr auch weiterhin fest zuschlagen könnt.\"" }
