entries[95052] = { ["name"] = "Arkaner Treibstoff", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig (60)\nBenötigt Stufe 90\nBenötigt Offensive der Kirin Tor\n- Respektvoll\nBenutzen: Verbraucht einen arkanen Fokus, um Euch vorwärts zu katapultieren. Kann nur während des Szenarios Schatzkammer des Donnerkönigs verwendet werden. (10 Sek. Abklingzeit)\nVerkaufspreis:" }
